import {
  partLineItemVariant,
  laborLineItemVariant,
  bicycleLineItemVariant,
} from './line-item-variants.js'

// ---------------------------------------------------------------------------
// Customer Order Line Item — composed from shared variants
// ---------------------------------------------------------------------------

/** Part line item for customer orders — allows nullable partId for ad-hoc items */
const customerOrderPartSchema = z.object({
  ...partLineItemVariant.toSchema().shape,
  partId: z.string().nullable().optional(),
})

/** Labor line item for customer orders — uses shared labor variant */
const customerOrderLaborSchema = laborLineItemVariant.toSchema()

/** Bicycle line item for customer orders — uses shared bicycle variant */
const customerOrderBicycleSchema = bicycleLineItemVariant.toSchema()

/** Discriminated union for creating a customer order line item */
export const customerOrderLineItemSchema = z.discriminatedUnion('lineType', [
  customerOrderPartSchema,
  customerOrderLaborSchema,
  customerOrderBicycleSchema,
])

export type CustomerOrderLineItem = z.infer<typeof customerOrderLineItemSchema>

/** Input for creating a customer order with optional deposit */
export const createCustomerOrderInputSchema = z.object({
  customerId: z.string().min(1, 'customerId is required'),
  lineItems: z.array(customerOrderLineItemSchema).min(1, 'At least one line item is required'),
  depositAmount: z.number().int().nonnegative('depositAmount must be non-negative').nullable().optional(),
  paymentMethod: paymentMethodSchema.nullable().optional(),
  expectedDeliveryDate: z.string().datetime().nullable().optional(),
  internalNotes: z.string().max(2000).nullable().optional(),
}).refine(
  (data) => {
    // If depositAmount > 0, paymentMethod must be provided
    if ((data.depositAmount ?? 0) > 0 && !data.paymentMethod) {
      return false
    }
    return true
  },
  { message: 'paymentMethod is required when depositAmount > 0', path: ['paymentMethod'] }
)

export type CreateCustomerOrderInput = z.infer<typeof createCustomerOrderInputSchema>

/** Customer order status */
export const customerOrderStatusSchema = z.enum(['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'])
export type CustomerOrderStatus = z.infer<typeof customerOrderStatusSchema>

// Repair Line Item Type
// ---------------------------------------------------------------------------

export const repairLineItemTypeSchema = z.enum(['part', 'labor'])

/** A valid line item type for repairs */
export type RepairLineItemType = z.infer<typeof repairLineItemTypeSchema>

// ---------------------------------------------------------------------------
// Customer Mode — existing or new customer during intake
// ---------------------------------------------------------------------------

export const customerModeSchema = z.enum(['existing', 'new'])

/** Whether the intake form is selecting an existing or creating a new customer */
export type CustomerMode = z.infer<typeof customerModeSchema>

